mapper.select:
SELECT trailType, occurredAt, amount, status, resultMsg FROM ( SELECT 'PAY' AS trailType, ISNULL(p.paid_at, p.requested_at) AS occurredAt, p.amount AS amount, p.status AS status, CAST(NULL AS VARCHAR(200)) AS resultMsg FROM erp_bookstore_payment p WHERE p.payment_id = #{paymentId}
UNION ALL
SELECT 'CANCEL', ISNULL(c.canceled_at, c.requested_at), -c.cancel_amount, c.status, c.result_msg FROM erp_bookstore_payment_cancel c WHERE c.payment_id = #{paymentId} ) t ORDER BY occurredAt DESC
